alibaba-compressed-mean.reference_sql:
SELECT 
  ROUND(SUM(item_count * order_occurrences) / SUM(order_occurrences), 1) AS mean
FROM items_per_order;

invalid-search-pct.reference_sql:
SELECT
  ROUND(100.0 * SUM(CASE WHEN is_invalid = 1 OR num_results = 0 THEN 1 ELSE 0 END) / COUNT(*), 2) AS invalid_search_pct
FROM search_category;

signup-confirmation-rate.reference_sql:
SELECT ROUND(COUNT(DISTINCT t.email_id) / COUNT(DISTINCT e.email_id), 2) AS confirm_rate
FROM emails e
LEFT JOIN texts t ON e.email_id = t.email_id AND t.signup_action = 'Confirmed';

snowflake-webinar-popularity.reference_sql:
SELECT
  ROUND(100.0 * SUM(CASE WHEN event_type = 'webinar' THEN 1 ELSE 0 END) / COUNT(*), 2) AS webinar_pct
FROM webinar_attendance;

sql-second-highest-salary.reference_sql:
SELECT MAX(salary) AS second_highest_salary
FROM employee
WHERE salary < (SELECT MAX(salary) FROM employee);

uncategorized-calls-percentage.reference_sql:
SELECT
  ROUND(100.0 * SUM(CASE WHEN call_category IS NULL OR LOWER(call_category) = 'n/a' THEN 1 ELSE 0 END) / COUNT(*), 1) AS call_percentage
FROM callers;
